cases.text:
Convert this Deepvue indicator so it works on this chart:
globalThis.indicator = {
  name: 'Ten Day High',
  panel: 'overlay',
  params: { len: { type: 'number', default: 10 } },
  outputs: { hi: { type: 'line', color: '#2196F3' } },
  compute(bar) {
    return { hi: bar.ta.highest('high', bar.params.len) };
  },
};

globalThis.indicator = {
  name: 'Range',
  params: {},
  outputs: { r: { type: 'line' } },
  compute: (bar) => {
    const r = bar.high - bar.low;
    return { r };
  },
};
